/* Full business workspace inside the authenticated shell. Policy money stays in the ledger. */
const business={owner:null,ready:false,version:1,dirty:false,saving:false,timer:null,error:'',revision:0,referral:{links:{}},referralVersion:1,referralSearch:'',referralCategory:'All'};
function portalPageIsEditing(){return !!document.activeElement?.matches?.('input,textarea,select')||!!document.querySelector?.('#overlay .modal')}
async function portalSyncBusiness(){if(!business.ready||!portal.user||business.owner!==portal.user.id)return;const owner=business.owner;const [record,links]=await Promise.all([portal.client.from('sigma_workspaces').select('data,version').eq('owner_id',owner).maybeSingle(),portal.client.from('sigma_referral_settings').select('data,version').eq('id',true).single()]);if(portal.user?.id!==owner||business.owner!==owner)return;if(!record.error&&record.data&&!business.dirty&&!business.saving&&!portalPageIsEditing()&&Number(record.data.version)>business.version){businessApply(record.data.data);business.version=Number(record.data.version)}if(!links.error&&links.data&&portal.view!=='referral-settings'){business.referral=links.data.data;business.referralVersion=Number(links.data.version)}}
const businessNav=[['home','grid','My dashboard'],['refer','gift','Refer & Earn'],['brochures','file','Brochures'],['assistant','spark','AI assistant'],['policies','shield','My bookings'],['wallet','wallet','My statement'],['renewals','renew','My renewals'],['rates','percent','My rate card'],['prospects','target','My prospects'],['contacts','contact','My contacts'],['help','help','Help guide'],['settings','contact','Workspace settings'],['integrations','lock','Connections']];
const referralProducts=[
  ['term','Term','shield','Life & investments','Protection for your family','Explore cover options and client-provided term insurance links.','Term'],
  ['investment','Investment','trend','Life & investments','Plan for tomorrow','Savings, ULIP and investment enquiry resources.','Investment'],
  ['health','Health','heart','Insurance','Care for what matters','Individual and family health insurance resources.','Health'],
  ['travel','Travel','plane','Insurance','Every journey, covered','Domestic, international and student travel resources.','Travel'],
  ['car','Car','car','Motor','Get back on the road','Car cover, renewal and quote destinations.','Motor'],
  ['two-wheeler','Two-Wheeler','car','Motor','Cover for every ride','Two-wheeler cover and renewal destinations.','Motor'],
  ['commercial','Commercial Vehicle','briefcase','Motor','Keep business moving','Truck, taxi, fleet and bus insurance resources.','Motor'],
  ['personal-accident','Personal Accident','shield','Insurance','A little more reassurance','Individual and family personal accident enquiries.','Personal Accident'],
  ['group-health','Group Health','users','Business','A healthier team','Corporate, SME and startup health benefits.','Group Health'],
  ['group-pa','Group Personal Accident','users','Business','Protect your people','Employee and team accident cover resources.','Group PA'],
  ['fire','Fire Insurance','home','Business','Protect what you built','Property, shop and office insurance resources.','Fire & Burglary']
];
const referralExtras=[['loan','Loans','Loan enquiry link'],['ambassador','Ambassador','Partner onboarding link'],['claims','Claim assistance','Claims support link'],['brochures','Brochures','Product documents'],['employee','Employee corner','Team resources']];
function businessBlank(){return {db:{bookings:[],leads:[],contacts:[],network:[],activity:[]},workspace:{profile:{name:portal.profile?.full_name||'Partner',email:portal.profile?.email||'',phone:portal.profile?.phone||''},quotes:[],payouts:[],rates:[],assets:[],prospects:[],services:{},pinned:[]},wizard:null,quoteDraft:{kind:'health',customer:'',phone:'',city:'',caseType:'Fresh',sumInsured:'1000000',members:[{name:'',relation:'Self',age:''}],plans:[],note:'',variant:'Elite',pa:500000,port:false,portDetails:'',premiums:Array.from({length:8},()=>[0,0,0,0,0]),screenshots:[]}}}
function businessApply(data){const blank=businessBlank();db={...blank.db,...data.db,bookings:[]};for(const k of ['leads','contacts','network','activity'])if(!Array.isArray(db[k]))db[k]=[];for(const key of Object.keys(workspace))delete workspace[key];Object.assign(workspace,blank.workspace,data.workspace||{});for(const k of ['quotes','payouts','rates','assets','prospects','pinned'])if(!Array.isArray(workspace[k]))workspace[k]=[];workspace.profile={...blank.workspace.profile,...workspace.profile,email:portal.profile?.email||''};workspace.services||={};wizard=data.wizard||null;pendingFiles={};quoteDraft={...blank.quoteDraft,...data.quoteDraft};portalMirrorPolicies()}
function portalResetBusiness(){clearTimeout(business.timer);business.owner=null;business.ready=false;business.dirty=false;business.saving=false;business.saveTask=null;business.version=1;business.referral={links:{}};business.referralVersion=1;business.error='';business.revision++;businessApply({});db.bookings=[];for(const url of assetURLs.values())URL.revokeObjectURL(url);assetURLs.clear()}
function portalLoadBusiness(owner){if(business.owner===owner&&business.ready)return Promise.resolve();if(business.loadingOwner===owner&&business.loadPromise)return business.loadPromise;business.loadingOwner=owner;const task=portalLoadBusinessNow(owner);business.loadPromise=task;task.finally(()=>{if(business.loadPromise===task){business.loadPromise=null;business.loadingOwner=null}});return task}
async function portalLoadBusinessNow(owner){if(business.owner===owner&&business.ready)return;portalResetBusiness();business.owner=owner;try{const [row,config]=await Promise.all([portal.client.from('sigma_workspaces').select('data,version').eq('owner_id',owner).maybeSingle(),portal.client.from('sigma_referral_settings').select('data,version').eq('id',true).single()]);if(portal.user?.id!==owner||business.owner!==owner)return;if(row.error)throw row.error;if(config.error)throw config.error;businessApply(row.data?.data||{});business.version=Number(row.data?.version||1);business.referral=config.data.data||{links:{}};business.referralVersion=Number(config.data.version);business.ready=true;business.error=''}catch(e){business.error=portalError(e);business.ready=false}}
function businessSnapshot(){return {db:{leads:db.leads,contacts:db.contacts,network:db.network,activity:db.activity},workspace,wizard,quoteDraft}}
function portalSaveBusiness(){if(!portal.configured)return false;if(!portal.user||!business.ready||business.owner!==portal.user.id){business.error='Your business workspace is not connected. Reload before editing.';toast(business.error);return true}business.dirty=true;business.revision++;clearTimeout(business.timer);business.timer=setTimeout(()=>portalFlushBusiness(),450);businessStatus();return true}
async function portalFlushBusiness(){while(business.saveTask)await business.saveTask;if(!business.dirty)return !business.error;const task=portalFlushBusinessNow();business.saveTask=task;let result;try{result=await task}finally{if(business.saveTask===task)business.saveTask=null}return result&&business.dirty?portalFlushBusiness():result}
async function portalFlushBusinessNow(){if(business.saving||!business.dirty)return !business.error;const owner=business.owner,revision=business.revision,payload=structuredClone(businessSnapshot());business.saving=true;business.error='';businessStatus();try{const result=await portal.client.rpc('sigma_save_workspace',{p_data:payload,p_version:business.version});if(result.error)throw result.error;if(business.owner!==owner||portal.user?.id!==owner)return false;business.version=Number(result.data.version);if(business.revision===revision)business.dirty=false;return true}catch(e){if(business.owner===owner)business.error=portalError(e);return false}finally{if(business.owner===owner){business.saving=false;businessStatus();if(business.dirty&&!business.error){clearTimeout(business.timer);business.timer=setTimeout(()=>portalFlushBusiness(),150)}}}}
function businessStatus(){const el=document.querySelector('#business-save-status');if(el)el.innerHTML=business.error?`<span role="alert">Unsaved: ${pe(business.error)}</span>${portalButton('Download backup','businessBackup()','download')}${portalButton('Retry save','portalFlushBusiness()','renew')}`:business.saving?'Saving workspace…':business.dirty?'Changes waiting to save…':'Workspace saved to your account'}
function businessBackup(){fileDownload('sigma0nine-unsaved-workspace.json',JSON.stringify(businessSnapshot(),null,2),'application/json')}
globalThis.sigmaSaveWorkspace=portalSaveBusiness;
function portalMirrorPolicies(){if(!portal.user)return;db.bookings=portal.policies.map(p=>{const c=portalCreditFor(p);return {id:p.id,name:p.customer_name,phone:p.customer_mobile,product:p.product,insurer:p.insurer,policyNumber:p.policy_number,premium:Number(p.premium_paise)/100,date:(p.start_date||p.submitted_at||p.created_at||'').slice(0,10),renewal:p.expiry_date||'',status:p.status,pointsReceived:Number(c?.points||0),grossPoints:Number(c?.points||0),pointsDue:0,portalRecord:true}})}
function portalBusinessRoute(){let hash=location.hash.slice(1);if(hash==='sell')return 'refer';if(hash==='marketing')return 'brochures';if(hash==='agents'&&portalModeAdmin())return 'agents';if(hash==='leads')return 'leads';if(['refer','referral-settings','uncredited'].includes(hash)||hash.startsWith('refer-'))return hash;if(businessNav.some(n=>n[0]===hash)||hash==='leadform')return hash;if(['admin','partner','policyportal','dashboard','login','register',''].includes(hash))return 'home';if(['admin-ledger','statement'].includes(hash))return 'wallet';if(['admin-policies','mypolicies','bookings'].includes(hash))return 'policies';return 'home'}
function portalNavHTML(){const rows=portalModeAdmin()?[['home','grid','Admin overview'],['policies','shield','Review policies'],['uncredited','wallet','Award earnings'],['wallet','file','Earnings & payments'],['agents','users','Manage partners'],['brochures','file','Brochures'],['refer','gift','Refer & Earn'],['referral-settings','lock','Manage referral links']]:businessNav;return rows.map(([id,icon,label],i)=>`${!portalModeAdmin()&&[8,12].includes(i)?`<div class="navlabel navsep">${i===8?'CONNECTIONS':'RESOURCES'}</div>`:''}<button class="${portal.view===id||id==='refer'&&portal.view.startsWith('refer-')?'active':''}" title="${pe(label)}" onclick="portalRoute('${id}')">${I(icon)}${label}${portalModeAdmin()&&id==='uncredited'?`<span class="pill">${portal.policies.filter(p=>p.status==='Approved'&&!portalCreditFor(p)).length}</span>`:''}</button>`).join('')}
const businessLegacyGo=go;
go=function(id){if(!portal.configured)return businessLegacyGo(id);const map={dashboard:'home',sell:'refer',bookings:'policies',statement:'wallet'};current=id;category='All';filter='All';query='';fromDate='';toDate='';contactTab='All';portalRoute(map[id]||id)};
const businessMapBooking=mapBooking;
mapBooking=function(){return portal.configured?portalUploadForm():businessMapBooking()};
const businessViewBooking=viewBooking;
viewBooking=function(id){return portal.configured&&portal.policies.some(p=>p.id===id)?portalPolicyDetails(id):businessViewBooking(id)};
const browserPersistFile=persistFile,browserReadAttachment=readAttachment;
persistFile=async function(file,allowVideo=false){if(!portal.configured)return browserPersistFile(file,allowVideo);if(!portal.user||!business.ready)throw Error('Sign in and load your workspace first');if(!file||file.size===0||file.size>10485760)throw Error('Choose a file no larger than 10 MB');if(!(/^(image\/(png|jpeg|webp)|application\/pdf)$/.test(file.type)||/\.(csv|xlsx|xls)$/i.test(file.name)||allowVideo&&['video/mp4','video/webm'].includes(file.type)))throw Error('Choose a supported image, PDF, spreadsheet or video');const id=crypto.randomUUID(),path=portal.user.id+'/'+id+'/'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-150);const result=await portal.client.storage.from('sigma-workspace-files').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(result.error)throw result.error;return {id,path,name:file.name,type:file.type,size:file.size,bucket:'sigma-workspace-files'}};
readAttachment=async function(id){if(!portal.configured)return browserReadAttachment(id);const seen=new Set();function find(value){if(!value||typeof value!=='object'||seen.has(value))return null;seen.add(value);if(value.id===id&&value.bucket==='sigma-workspace-files')return value;for(const v of Object.values(value)){const found=find(v);if(found)return found}return null}const ref=find(businessSnapshot());if(!ref||!ref.path.startsWith(portal.user.id+'/'))throw Error('This file is not available to your account');const result=await portal.client.storage.from(ref.bucket).download(ref.path);if(result.error)throw result.error;return new File([result.data],ref.name,{type:ref.type})};
function portalWorkspacePage(){const v=portal.view;if(v==='refer')return referralPage();if(v.startsWith('refer-'))return referralProductPage(v.slice(6));if(v==='referral-settings')return referralSettingsPage();if(v==='uncredited')return portalUncreditedPage();if(v==='agents')return portalAgentsPage();if(v==='brochures')return portalBrochuresPage();if(v==='wallet')return portalWalletPage();if(v==='policies')return portalOverviewPage();if(v==='home')return portalModeAdmin()?portalAdminHome():portalPartnerHome();if(portalModeAdmin())return portalAdminHome();if(!business.ready)return heading('BUSINESS WORKSPACE','Workspace connection required','Policies and wallet remain available.')+portalInlineError(business.error)+portalButton('Reconnect workspace','portalLoadBusiness(portal.user.id).then(portalRender)','renew',true);current=v;const pages={marketing,assistant,renewals:portalRenewalsPage,rates:ratePage,leads,network,prospects:prospectPage,contacts,quotes,nivaquote:nivaQuotePage,savedquotes:savedQuotesPage,help,settings:settingsPage,integrations:portalConnectionsPage,leadform:leadFormPage};const html=(pages[v]||help)();return `<div class="business-save-bar" id="business-save-status"></div>`+html}
function portalPartnerHome(){const s=portal.summary,premium=portal.policies.reduce((sum,p)=>sum+Number(p.premium_paise||0),0),due=portal.policies.filter(p=>p.status==='Approved'&&p.expiry_date&&p.expiry_date>=dateISO()).length;return heading('PARTNER COMMAND CENTER','Business overview','Your policies, relationships and rewards. One connected workspace.',portalButton('Upload policy','portalUploadForm()','plus',true))+`<section class="business-hero"><div><span class="welcome-kicker">BUILT AROUND YOUR NEXT OPPORTUNITY</span><h2>Welcome back,<br><em>${pe(portal.profile.full_name)}.</em></h2><p>Grow your business. Keep every policy in view.<br>Give your customers a little more confidence.</p><div class="actions">${portalButton('Refer & Earn',"portalRoute('refer')",'gift',true)}${portalButton('View my bookings',"portalRoute('policies')",'shield')}</div></div><div class="business-hero-symbol">${I('shield')}<span>YOUR GROWTH, CONNECTED.</span></div></section><div class="metrics">${metric('Business volume',PortalCore.money(premium),'trend',(s.total||0)+' policy submissions')}${metric('Approved policies',s.approved||0,'check','Reviewed by the team')}${metric('Earned amount',PortalCore.money(s.amount_paise||0),'wallet','Your account balance')}${metric('Awaiting approval',s.pending||0,'clock','Track the review queue')}</div><section class="card pad"><div class="sectiontitle"><h2>Start a new opportunity</h2>${portalButton('All products',"portalRoute('refer')")}</div><div class="business-shortcuts">${referralProducts.slice(0,6).map(p=>`<button onclick="portalRoute('refer-${p[0]}')">${I(p[2])}<strong>${pe(p[1])}</strong><small>Explore & refer</small></button>`).join('')}</div></section><div class="business-grid"><section class="card pad"><div class="sectiontitle"><h2>Business trend</h2><span class="subtle">Last 6 months · submitted premium</span></div>${actualTrend()}</section><section class="card pad"><span class="eyebrow">YOUR NEXT MOVE</span><h2>Keep good things moving.</h2><div class="business-next"><span>Policies with future renewals <strong>${due}</strong></span><span>Approved policies <strong>${s.approved||0}</strong></span></div><div class="actions">${portalButton('My renewals',"portalRoute('renewals')",'renew')}</div></section></div><section class="card pad"><div class="sectiontitle"><h2>Recent policy submissions</h2>${portalButton('View all',"portalRoute('policies')")}</div>${portalPolicyList()}</section>`}
function portalAdminHome(){return portalOverviewPage()+portalCreditCallout()}
function portalCreditCallout(){const waiting=portal.policies.filter(p=>p.status==='Approved'&&!portalCreditFor(p));return `<section class="credit-callout"><div>${I('wallet')}<h2>${waiting.length} approved ${waiting.length===1?'policy is':'policies are'} awaiting credit</h2><p>Choose a policy, review the submitting partner and award an earning amount.</p></div>${portalButton('Award earnings',"portalRoute('uncredited')",'plus',true)}</section>`}
function portalUncreditedPage(){const waiting=portal.policies.filter(p=>p.status==='Approved'&&!portalCreditFor(p));return heading('PARTNER REWARDS','Award earnings','The recipient is always the partner who uploaded the approved policy.',portalButton('Refresh','portalRefresh()','renew'))+`<div class="credit-explainer"><span>1. Review & approve</span><span>2. Enter earning amount</span><span>3. Confirm partner credit</span></div><div class="record-grid">${waiting.map(p=>`<article class="card pad"><span class="badge">APPROVED · NOT CREDITED</span><h2>${pe(p.customer_name)}</h2><p>${pe(p.product)} · ${pe(p.policy_number||'Policy number not supplied')}</p><div class="portal-credit-recipient"><span class="initial">${portalInitial(portalOwner(p).full_name)}</span><div><strong>${pe(portalOwner(p).full_name)}</strong><small>${pe(portalOwner(p).email)}</small></div></div>${portalButton('Award earnings',`portalCreditForm('${p.id}')`,'wallet',true)}${portalButton('View policy',`portalPolicyDetails('${p.id}')`,'file')}</article>`).join('')||`<section class="card pad"><h2>No approved policies awaiting credit</h2><p>Approve a pending policy first. The amount form opens immediately after approval.</p>${portalButton('Review pending policies',"portalRoute('policies')",'shield',true)}</section>`}</div>${portal.hasMore?'<p class="notice">More submissions are available. Load more records in Review policies to find older uncredited policies.</p>':''}`}
function portalRenewalRows(){const now=dateISO(),period=['Upcoming','Next 30 days','Expired','All'].includes(dateWindow)?dateWindow:'Upcoming';const rows=portal.policies.filter(p=>p.expiry_date&&[p.customer_name,p.customer_mobile,p.policy_number,p.insurer].join(' ').toLowerCase().includes(query.toLowerCase())&&(period==='All'||period==='Expired'&&p.expiry_date<now||period==='Upcoming'&&p.expiry_date>=now||period==='Next 30 days'&&p.expiry_date>=now&&p.expiry_date<=new Date(Date.now()+30*86400000).toISOString().slice(0,10)));return rows.map(p=>'<tr><td>'+pe(p.customer_name)+'<small>'+pe(p.customer_mobile)+'</small></td><td>'+pe(p.product)+' · '+pe(p.insurer)+'</td><td>'+pe(p.expiry_date)+'</td><td>'+portalStatus(p.status)+'</td><td>'+portalButton('View',"portalPolicyDetails('"+p.id+"')",'file')+'</td></tr>').join('')||'<tr><td colspan="5" class="empty">No matching expiry dates. Include an expiry date when uploading a policy.</td></tr>'}
function portalRenewalsPage(){return heading('RETENTION DESK','My renewals','Expiry dates from your submitted policy records.',portalButton('Upload renewal','portalUploadForm()','plus',true))+'<div class="toolbar"><div class="searchbox">'+I('search')+'<input aria-label="Search renewals" placeholder="Search customer, insurer or policy…" value="'+pe(query)+'" oninput="query=this.value;document.querySelector(\'#business-renewal-rows\').innerHTML=portalRenewalRows()"></div><select aria-label="Renewal period" onchange="dateWindow=this.value;render()">'+optionsHTML(['Upcoming','Next 30 days','Expired','All'],dateWindow,false)+'</select></div><section class="card tablewrap"><table><thead><tr><th>Customer</th><th>Product / insurer</th><th>Expiry</th><th>Policy status</th><th>Action</th></tr></thead><tbody id="business-renewal-rows">'+portalRenewalRows()+'</tbody></table></section>'}
function portalConnectionsPage(){return heading('CONNECTED SERVICES','Your workspace connections','See what is live and which client services still need connecting.')+`<section class="card tablewrap"><table><thead><tr><th>Service</th><th>Status</th><th>Details</th></tr></thead><tbody>${[['Account & policy approval','Connected','Supabase Auth, private uploads and admin review'],['Earnings & payments','Connected','One-time policy credits with an immutable ledger'],['Business workspace','Connected','Account-owned leads, contacts, prospects, drafts, rates and quotes'],['Workspace documents','Connected','Private account-owned file storage'],['Refer & Earn','Ready for client links','Product catalogue and administrator-managed destinations'],['AI / WhatsApp automation','Provider required','Draft previews work; automated generation and delivery are not connected'],['Insurer issuance / bank payouts','Provider required','No insurer-issued quotes or bank transfers are performed']].map(r=>`<tr><td>${r[0]}</td><td><span class="badge">${r[1]}</span></td><td class="wrap">${r[2]}</td></tr>`).join('')}</tbody></table></section>`}
function referralURL(key){try{const url=new URL(business.referral.links?.[key]||'');if(url.protocol!=='https:'||url.username||url.password)return '';return url.href}catch{return ''}}
function referralLink(key,label,cls='primary'){const url=referralURL(key);return url?`<a class="${cls} referral-link" href="${pe(url)}" target="_blank" rel="noopener noreferrer">${pe(label)}${I('chevron')}</a>`:`<span class="referral-pending">${I('clock')}Link pending</span>`}
function referralPage(){const rows=referralProducts.filter(p=>(business.referralCategory==='All'||p[3]===business.referralCategory)&&p.join(' ').toLowerCase().includes(business.referralSearch.toLowerCase()));return `<section class="referral-hero"><div><span class="welcome-kicker">SIGMA0NINE PARTNER OPPORTUNITIES</span><h1>A connection today.<br><em>An opportunity tomorrow.</em></h1><p>Insurance, investments and more.<br>Find the right destination for every customer.</p><div class="actions">${portalModeAdmin()?portalButton('Manage client links',"portalRoute('referral-settings')",'lock',true)+portalButton('Review policies',"portalRoute('policies')",'shield'):portalButton('Create a lead','portalLeadChooser()','plus',true)}</div></div><div class="referral-art">${I('gift')}<span>REFER.<br>CONNECT.<br>GROW.</span></div></section><div class="referral-toolbar"><div class="searchbox">${I('search')}<input aria-label="Search referral products" placeholder="What is your customer looking for?" value="${pe(business.referralSearch)}" oninput="business.referralSearch=this.value;referralUpdateCards()"></div><div class="tabs">${['All','Insurance','Motor','Life & investments','Business'].map(v=>`<button class="${business.referralCategory===v?'active':''}" onclick="business.referralCategory='${v}';portalRender()">${v}</button>`).join('')}</div></div><div class="sectiontitle"><div><span class="eyebrow">EXPLORE THE POSSIBILITIES</span><h2>One place. Every opportunity.</h2></div><span class="subtle">11 product categories</span></div><div id="referral-cards" class="referral-cards">${referralCards(rows)}</div><div class="referral-bottom"><section class="card pad"><h2>Useful partner resources</h2><div class="resource-links">${referralExtras.filter(p=>p[0]!=='demat').map(([key,label])=>`<div><strong>${pe(label)}</strong>${referralLink(key,'Open','quiet')}</div>`).join('')}</div></section></div><p class="referral-disclosure">Product availability, referral terms and payouts are set by your client/provider. Destinations marked “Link pending” will activate when the client supplies their links.</p>`}
function referralCards(rows){return rows.map(p=>`<button class="referral-product" onclick="portalRoute('refer-${p[0]}')"><span class="referral-product-icon">${I(p[2])}</span><span class="referral-product-group">${pe(p[3])}</span><strong>${pe(p[1])}</strong><span>${pe(p[4])}</span><span class="referral-product-foot">Explore options ${I('chevron')}</span></button>`).join('')||'<p>No product matches this search.</p>'}
function referralUpdateCards(){const rows=referralProducts.filter(p=>(business.referralCategory==='All'||p[3]===business.referralCategory)&&p.join(' ').toLowerCase().includes(business.referralSearch.toLowerCase()));document.querySelector('#referral-cards').innerHTML=referralCards(rows)}
function referralSupport(){const phone=String(business.referral.supportPhone||'').replace(/[^+0-9]/g,'');return phone?`<a class="primary referral-link" href="tel:${pe(phone)}">${I('phone')}Call customer care</a>`:'<span class="referral-pending">Customer-care number pending</span>'}
function referralProductPage(key){const p=referralProducts.find(p=>p[0]===key);if(!p)return referralPage();return heading('REFER & EARN',pe(p[1]),pe(p[5]),portalButton('All opportunities',"portalRoute('refer')",'grid'))+`<section class="referral-detail-hero"><span>${I(p[2])}</span><div><span class="eyebrow">${pe(p[3])}</span><h2>${pe(p[4])}</h2><p>Choose a client-provided destination or save a customer enquiry in your workspace.</p></div></section><div class="referral-destinations">${[['', 'Provider / application','Open the official client-provided product destination.','Open destination'],['-quote','Quote resources','Check the client’s quote tool or resource page.','Check quotes'],['-brochure','Product brochure','View product information supplied by your client.','View brochure']].map(([suffix,title,text,label])=>`<section class="card pad"><span class="service-icon">${I(suffix==='-brochure'?'file':suffix?'trend':'shield')}</span><h2>${title}</h2><p>${text}</p>${referralLink(key+suffix,label)}</section>`).join('')}</div><section class="card pad referral-enquiry"><div><h2>Prefer an assisted conversation?</h2><p>Record your customer’s requirements and follow the enquiry in My leads.</p></div>${portalModeAdmin()?referralSupport():portalButton('Create '+p[1]+' lead',`referralStartLead('${p[0]}')`,'plus',true)}</section>`}
function referralSettingsPage(){if(!portalModeAdmin())return portalInlineError('Admin access required');return heading('REFERRAL ADMINISTRATION','Manage client links','Save client-provided HTTPS links here. They appear in every partner’s Refer & Earn section.',portalButton('Preview catalogue',"portalRoute('refer')",'gift'))+`<form onsubmit="event.preventDefault();saveReferralSettings(this)"><section class="card pad"><h2>Customer support</h2><label class="field">Customer-care number<input name="supportPhone" type="tel" maxlength="25" value="${pe(business.referral.supportPhone||'')}" placeholder="+91…"></label></section><section class="card pad" style="margin-top:20px"><h2>Product destinations</h2><p>Leave unavailable links empty. Partners see a clear pending label.</p><div class="referral-settings-grid">${referralProducts.map(p=>`<fieldset><legend>${pe(p[1])}</legend>${[['','Application / provider'],['-quote','Quote tool'],['-brochure','Brochure']].map(([s,label])=>`<label class="field">${label}<input type="url" name="link-${p[0]+s}" maxlength="4000" placeholder="https://…" value="${pe(business.referral.links?.[p[0]+s]||'')}"></label>`).join('')}</fieldset>`).join('')}</div><h2>Insurer quotes & resources</h2><div class="formgrid">${referralExtras.map(([key,label])=>`<label class="field">${pe(label)}<input type="url" name="link-${key}" maxlength="4000" placeholder="https://…" value="${pe(business.referral.links?.[key]||'')}"></label>`).join('')}</div><div class="portal-form-error" role="alert"></div><div class="modalfoot"><button class="primary" type="submit">Save client links</button></div></section></form>`}
async function saveReferralSettings(form){const button=form.querySelector('button[type=submit]');button.disabled=true;try{const values=new FormData(form),links={};for(const [name,value] of values){if(!name.startsWith('link-'))continue;const text=String(value).trim();if(text){const url=new URL(text);if(url.protocol!=='https:'||url.username||url.password)throw Error('Use HTTPS links without embedded passwords');}links[name.slice(5)]=text}const phone=String(values.get('supportPhone')||'').trim();if(!/^[+0-9 ()-]{0,25}$/.test(phone))throw Error('Enter a valid customer-care number');const result=await portal.client.rpc('sigma_save_referral_settings',{p_data:{links,supportPhone:phone},p_version:business.referralVersion});if(result.error)throw result.error;business.referral=result.data.data;business.referralVersion=Number(result.data.version);toast('Client links saved for all partners');portalRoute('refer')}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}finally{button.disabled=false}}
connectionNote=function(){return portal.configured?'<div class="storage-status">'+I('lock')+' Account-owned business records · private cloud documents</div>':'<div class="storage-status">Browser workspace · saved on this device</div>'};
window.addEventListener('beforeunload',event=>{if(business.dirty){event.preventDefault();event.returnValue=''}});

const cloudLeadFormPage=leadFormPage;leadFormPage=function(){let html=cloudLeadFormPage();return portal.configured?html.replace('Your draft is automatically saved in this browser.','Your draft is saved to your account.').replace('Documents stay in this browser. AI extraction and team approval need a connected service.','Documents are private to your account. Leads are enquiries; upload a policy separately for admin approval.'):html};

WORKFLOWS['Personal Accident']=[{title:'Customer details',fields:[...customerFields,F('dob','Date of birth','date',true),F('occupation','Occupation','text',true)]},{title:'Cover requirements',fields:[F('sumInsured','Required sum insured (₹)','number',true),F('annualIncome','Annual income (₹)','number'),F('familyCover','Cover for','select',true,['Individual','Family']),F('notes','Additional requirements','textarea')]}];
function portalLeadChooser(){modal('Choose a lead product','<p>Select the customer’s requirement.</p><div class="business-shortcuts">'+Object.keys(WORKFLOWS).map(p=>'<button onclick="startLead(\''+pe(p)+'\')">'+I('shield')+'<strong>'+pe(p)+'</strong></button>').join('')+'</div>')}
function referralStartLead(key){const p=referralProducts.find(p=>p[0]===key);if(!p)return;startLead(p[6]);if(key==='commercial')wizard.data.vehicleType='Commercial vehicle';if(key==='two-wheeler')wizard.data.vehicleType='Two wheeler';saveWizard()}
const cloudSettingsPage=settingsPage;settingsPage=function(){const html=cloudSettingsPage();return portal.configured?html.replace('Manage your advisor details, links and browser data.','Manage your advisor details, links and account-owned data.').replace('Uploaded document files are stored separately in this browser and are not inside the backup.','Uploaded documents are in private cloud storage and are not inside the JSON backup. Imported payout records are personal reference records; they cannot change your live wallet.'):html};

function portalPageLabel(){if(portal.view.startsWith('refer-'))return 'Refer & Earn';const labels=portalModeAdmin()?{home:'Admin overview',policies:'Review policies',uncredited:'Award earnings',wallet:'Earnings & payments',agents:'Manage partners',brochures:'Brochures',refer:'Refer & Earn','referral-settings':'Manage referral links'}:{};return labels[portal.view]||businessNav.find(n=>n[0]===portal.view)?.[2]||'Workspace'}
